import {buildComparison} from './comparison-model.mjs';
import {predictionEvents} from './prediction-model.mjs';
export function makeExam(random=Math.random){const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};const questions=[];for(const kind of ['pressure','jam','sensor']){const model=buildComparison(kind),events=predictionEvents(model),catalog=[...new Map(events.flatMap(e=>e.options).map(o=>[o.id,o])).values()],pool=[];for(const e of events.filter(e=>e.index>=model.first&&e.index<=model.alarm)){const changes=e.changes.filter(c=>c.bank==='fault');for(const answer of changes){const distractors=catalog.filter(o=>!changes.some(c=>c.id===o.id)).slice(0,3);pool.push({...e,bank:'fault',answer,options:shuffle([{id:answer.id,label:answer.label,type:answer.type},...distractors])});}}const chosen=[];for(const e of shuffle(pool))if(!chosen.some(q=>q.answer.id===e.answer.id)&&chosen.length<2)chosen.push(e);questions.push(...chosen.map(e=>({...e,kind})));}return {id:crypto.randomUUID(),date:new Date().toISOString(),questions:shuffle(questions),answers:[],status:'active'};}
export function examRecords(exam){return exam.answers.map((id,i)=>{const e=exam.questions[i],correct=id===e.answer.id;return {id:exam.id+':'+i,date:exam.date,completedAt:exam.finishedAt,kind:e.kind,signal:e.answer.id,label:e.answer.label,resolved:true,points:correct?100:0,errors:correct?0:1,hints:0,revealed:false,wrong:correct?[]:[e.options.find(o=>o.id===id)?.label||'Sin respuesta'],review:true,level:'exam',exam:true,correct};});}
export function createWeeklyExam(host,{storage,ready,loadExperiment,seek,refresh,save,onSaved}){let exam=null,open=false,warning='';const key='mecanica.weekly-exam.v1';try{const saved=JSON.parse(storage.getItem(key)||'null');if(saved&&Array.isArray(saved.questions)&&saved.questions.length===6&&Array.isArray(saved.answers)&&saved.answers.length<=6&&['active','finished','abandoned'].includes(saved.status)&&saved.questions.every(e=>['pressure','jam','sensor'].includes(e.kind)&&Number.isInteger(e.index)&&e.answer&&Array.isArray(e.options)))exam=saved;}catch{warning='No se pudo recuperar el examen local.';}
 const persist=()=>{try{storage.setItem(key,JSON.stringify(exam));}catch{warning='El examen solo se conserva en esta sesión.';}};
 const view=(e,after=false)=>{loadExperiment(e.kind);seek(e.index-(after?0:1));};
 function finish(){exam.status='finished';exam.finishedAt=new Date().toISOString();examRecords(exam).forEach(save);persist();onSaved();refresh();}
 function render(){host.replaceChildren();const el=(tag,text,parent=host)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};el('h2','Examen semanal · casos sorpresa');el('p','6 predicciones de tres averías simuladas. Una respuesta por pregunta, sin pistas ni corrección hasta terminar. Es práctica libre: puedes repetir. Al finalizar, cada acierto vale 100 y cada error 0; la nota es la media. Los errores ajustan tus repasos y no cuentan para la meta diaria.');if(warning)el('p',warning);
 if(!open){const b=el('button',exam?.status==='active'?'Continuar examen pendiente':'Comenzar examen sorpresa');b.id='examStart';b.disabled=!ready();b.onclick=()=>{if(exam?.status!=='active'){exam=makeExam();persist();}open=true;if(exam.answers.length===6)finish();else view(exam.questions[exam.answers.length]);};if(exam?.status==='finished'){const b=el('button','Revisar último examen');b.onclick=()=>{open=true;refresh();};}return;}
 const exit=el('button',exam.status==='active'?'Guardar y salir':'Cerrar revisión');exit.id='examExit';exit.onclick=()=>{open=false;persist();refresh();};
 if(exam.status==='active'){const n=exam.answers.length,e=exam.questions[n];el('h3','Pregunta '+(n+1)+' / 6 · banco '+(e.bank==='fault'?'averiado':'normal'));el('p','Observa el scan anterior. ¿Qué señal cambiará a los '+(e.index*.02).toFixed(2)+' s?');const choices=el('div','');choices.id='examChoices';choices.className='actions';for(const o of e.options){const b=el('button',o.label,choices);b.onclick=()=>{if(exam.status!=='active'||exam.answers.length!==n)return;exam.answers.push(o.id);persist();if(exam.answers.length===6)finish();else view(exam.questions[exam.answers.length]);};}return;}
 const records=examRecords(exam),score=Math.round(records.reduce((n,r)=>n+r.points,0)/6);el('h3','Resultado: '+score+'/100 · '+records.filter(r=>r.correct).length+' / 6 aciertos');el('p','Resultados guardados. Tus errores ya alimentan las dificultades, los intervalos y el plan semanal. Revisa antes/después para relacionar entrada, contacto y salida.');
 for(const [i,e]of exam.questions.entries()){const r=records[i],card=el('article','');card.className='exam-review';el('h4',(i+1)+' · '+(r.correct?'Correcto':'Para repasar')+' · '+e.answer.label,card);el('p','Elegiste: '+(e.options.find(o=>o.id===exam.answers[i])?.label||'—')+(r.correct?'. ':'. Esa opción no cambia en este scan. ')+'Cambia: '+e.answer.label+' '+e.answer.from+' → '+e.answer.to+'.',card);el('p',({pressure:'La presión cae: PS=0 activa P01; el PLC retira las salidas. Sin presión el pistón no se mueve.',jam:'El atasco inmoviliza A aunque haya orden. Sin a1, la supervisión termina disparando timeout.',sensor:'a1 pierde señal por momentos aun con A en el extremo. El TON se reinicia y la falta de confirmación puede disparar timeout.'})[e.kind],card);el('p','En este scan: '+e.changes.map(c=>(c.bank==='fault'?'Averiado':'Normal')+' '+c.label+' '+c.from+'→'+c.to).join(' · '),card);for(const [label,after]of [['Ver antes',false],['Ver cambio',true]]){const b=el('button',label,card);b.disabled=!ready();b.onclick=()=>view(e,after);}}
 }
 return {render,active:()=>open,testing:()=>open&&exam?.status==='active',state:()=>exam};
}
